{
  "root_cause": "The navigation controller's `navigate` function is called each time `autoComplete.start` renders a new results list, adding a duplicate `keydown` listener on the input field. Multiple listeners cause stale `currentFocus` states, leading to incorrect item activation when Enter is pressed.",
  "repair_strategy": "Add a guard flag (`_navListenerAttached`) to the input field to ensure the navigation keydown listener is attached only once per instance, preventing duplicate accumulations.",
  "edits": [
    {
      "path": "src/controllers/navigationController.js",
      "sha256": "cb38337c041e8e0543c4f7b31666374956d6dc85011604e12ff127c9bf67ddde",
      "before": "import { closeAllLists } from "./listController";
import eventEmitter from "../utils/eventEmitter";

/**
 * List navigation function initializer
 *
 * @param {Object} config - autoComplete configurations
 * @param {Object} dataFeedback - The available data object
 *
 */
const navigate = (config, dataFeedback) => {
  // Reset focus state
  let currentFocus = -1;

  /**
   * Update list item state
   *
   * @param {Object} event - The `keydown` event Object
   * @param {Array <elements>} list - The array of list items
   * @param {Boolean} state - Of the arrow Down/Up
   * @param {Object} config - autoComplete configurations
   *
   */
  const update = (event, list, state, config) => {
    event.preventDefault();
    if (state) {
      // If the arrow DOWN or TAB key is pressed
      // increase the currentFocus
      currentFocus++;
    } else {
      // If the arrow UP or TAB key is pressed
      // decrease the currentFocus
      currentFocus--;
    }
    // and add "active" class to the list item
    addActive(list);
    config.inputField.setAttribute("aria-activedescendant", list[currentFocus].id);
    /**
     * @emits {navigation} Emits Event on results list navigation
     **/
    eventEmitter(
      event.srcElement,
      { event, ...dataFeedback, selection: dataFeedback.results[currentFocus] },
      "navigation"
    );
  };

  /**
   * Remove list item active state
   *
   * @param {Array <elements>} list - The array of list items
   *
   */
  const removeActive = (list) => {
    // Remove "active" class from all list items
    for (let index = 0; index < list.length; index++) {
      // Remove "active" class from the item
      list[index].removeAttribute("aria-selected");
      // list[index].setAttribute("aria-selected", "false");
      list[index].classList.remove("autoComplete_selected");
    }
  };

  /**
   * Add active state to list item
   *
   * @param {Array <elements>} list - The array of list items
   *
   */
  const addActive = (list) => {
    // Add "active" class to a list item
    if (!list) return false;
    // Remove "active" class from all list items
    removeActive(list);
    if (currentFocus >= list.length) currentFocus = 0;
    if (currentFocus < 0) currentFocus = list.length - 1;
    // Add "active" class to the item
    list[currentFocus].setAttribute("aria-selected", "true");
    list[currentFocus].classList.add("autoComplete_selected");
  };

  /**
   * List Navigation Function
   *
   * @param {Object} event - The `keydown` event Object
   *
   */
  const navigation = (event) => {
    let list = document.getElementById(config.resultsList.idName);

    if (!list) return config.inputField.removeEventListener("keydown", navigate);

    list = list.getElementsByTagName(config.resultItem.element);

    if (event.keyCode === 27) {
      // If the ESC key is pressed
      // Clear Input value
      config.inputField.value = "";
      // Closes open lists
      closeAllLists(config);
    } else if (event.keyCode === 40 || event.keyCode === 9) {
      // Update list items state
      update(event, list, true, config);
    } else if (event.keyCode === 38 || event.keyCode === 9) {
      // Update list items state
      update(event, list, false, config);
    } else if (event.keyCode === 13) {
      // If the ENTER key is pressed
      // prevent the form from its default behaviour "being submitted"
      event.preventDefault();
      if (currentFocus > -1) {
        // and simulate a click on the selected "active" item
        if (list) list[currentFocus].click();
      }
    }
  };

  const navigate = config.resultsList.navigation || navigation;
  /**
   * @listens {keydown} Listens to all `keydown` events on the input field
   **/
  config.inputField.addEventListener("keydown", navigate);
};

export { navigate };",
      "after": "import { closeAllLists } from "./listController";
import eventEmitter from "../utils/eventEmitter";

/**
 * List navigation function initializer
 *
 * @param {Object} config - autoComplete configurations
 * @param {Object} dataFeedback - The available data object
 *
 */
const navigate = (config, dataFeedback) => {
  // Reset focus state
  let currentFocus = -1;

  /**
   * Update list item state
   *
   * @param {Object} event - The `keydown` event Object
   * @param {Array <elements>} list - The array of list items
   * @param {Boolean} state - Of the arrow Down/Up
   * @param {Object} config - autoComplete configurations
   *
   */
  const update = (event, list, state, config) => {
    event.preventDefault();
    if (state) {
      // If the arrow DOWN or TAB key is pressed
      // increase the currentFocus
      currentFocus++;
    } else {
      // If the arrow UP or TAB key is pressed
      // decrease the currentFocus
      currentFocus--;
    }
    // and add "active" class to the list item
    addActive(list);
    config.inputField.setAttribute("aria-activedescendant", list[currentFocus].id);
    /**
     * @emits {navigation} Emits Event on results list navigation
     **/
    eventEmitter(
      event.srcElement,
      { event, ...dataFeedback, selection: dataFeedback.results[currentFocus] },
      "navigation"
    );
  };

  /**
   * Remove list item active state
   *
   * @param {Array <elements>} list - The array of list items
   *
   */
  const removeActive = (list) => {
    // Remove "active" class from all list items
    for (let index = 0; index < list.length; index++) {
      // Remove "active" class from the item
      list[index].removeAttribute("aria-selected");
      // list[index].setAttribute("aria-selected", "false");
      list[index].classList.remove("autoComplete_selected");
    }
  };

  /**
   * Add active state to list item
   *
   * @param {Array <elements>} list - The array of list items
   *
   */
  const addActive = (list) => {
    // Add "active" class to a list item
    if (!list) return false;
    // Remove "active" class from all list items
    removeActive(list);
    if (currentFocus >= list.length) currentFocus = 0;
    if (currentFocus < 0) currentFocus = list.length - 1;
    // Add "active" class to the item
    list[currentFocus].setAttribute("aria-selected", "true");
    list[currentFocus].classList.add("autoComplete_selected");
  };

  /**
   * List Navigation Function
   *
   * @param {Object} event - The `keydown` event Object
   *
   */
  const navigation = (event) => {
    let list = document.getElementById(config.resultsList.idName);

    if (!list) return config.inputField.removeEventListener("keydown", navigate);

    list = list.getElementsByTagName(config.resultItem.element);

    if (event.keyCode === 27) {
      // If the ESC key is pressed
      // Clear Input value
      config.inputField.value = "";
      // Closes open lists
      closeAllLists(config);
    } else if (event.keyCode === 40 || event.keyCode === 9) {
      // Update list items state
      update(event, list, true, config);
    } else if (event.keyCode === 38 || event.keyCode === 9) {
      // Update list items state
      update(event, list, false, config);
    } else if (event.keyCode === 13) {
      // If the ENTER key is pressed
      // prevent the form from its default behaviour "being submitted"
      event.preventDefault();
      if (currentFocus > -1) {
        // and simulate a click on the selected "active" item
        if (list) list[currentFocus].click();
      }
    }
  };

  const navigate = config.resultsList.navigation || navigation;
  /**
   * @listens {keydown} Listens to all `keydown` events on the input field
   **/
  if (!config.inputField._navListenerAttached) {
    config.inputField.addEventListener("keydown", navigate);
    config.inputField._navListenerAttached = true;
  }
};

export { navigate };"
    }
  ],
  "expected_accessibility_effect": "Keyboard users will reliably move focus through suggestions with ArrowDown/ArrowUp, and pressing Enter will commit the currently highlighted suggestion, preserving the combobox pattern.",
  "functional_risks": [
    "If the input field is replaced or re‑used by another autoComplete instance, the flag may prevent attaching a listener when needed.",
    "If a custom `navigation` function is provided via `resultsList.navigation`, the guard still applies and could suppress a listener that expects to be re‑added on each render."
  ],
  "verification_requirements": [
    "After typing "bl" then pressing ArrowDown once and Enter, the input value must be "Blackberry".",
    "ArrowDown and ArrowUp should correctly wrap and update `aria-activedescendant` and `aria-selected` on the appropriate list item.",
    "Escape should clear the input and close the suggestion list.",
    "Tab should behave as an arrow down when the list is open and move focus away when closed."
  ]
}

reasoning:
We need to analyze the problem.

The journey steps:

1. Seek #fruit (focus)
2. Type "b"
   Assertion: aria-expanded becomes true (so dropdown opens)
3. Press ArrowDown twice? Actually step sequence:
   After typing b, then press ArrowDown (first down) -> assertions none
   Then another ArrowDown (second down) -> assertion: aria-selected on #autoComplete_result_0 equals true

Wait reading frozen_journey_requirements:

[
 {"action":{"kind":"seek","maxTabs":24,"selector":"#fruit"},"assertions":[]},
 {"action":{"kind":"type","text":"b"},"assertions":[{"kind":"attribute","name":"aria-expanded","selector":"#fruit","value":"true"}]},
 {"action":{"key":"ArrowDown","kind":"press"},"assertions":[]},
 {"action":{"key":"ArrowDown","kind":"press"},"assertions":[{"kind":"attribute","name":"aria-selected","selector":"#autoComplete_result_0","value":"true"}]},
 {"action":{"kind":"type","text":"l"},"assertions":[{"kind":"text","selector":"#autoComplete_result_0","value":"Blackberry"}]},
 {"action":{"key":"ArrowDown","kind":"press"},"assertions":[{"kind":"attribute","name":"aria-selected","selector":"#autoComplete_result_0","value":"true"}]},
 {"action":{"key":"Enter","kind":"press"},"assertions":[{"kind":"form-data","name":"fruit","selector":"#order-form","value":["Blackberry"]}]}
]

Interpretation: Starting at blank input, type "b", dropdown shows suggestions starting with B: Banana, Bilberry, Blackberry, Blackcurrant, Blueberry, Boysenberry, Cranberry? Wait Cranberry doesn't start with C but maybe filtered by prefix? Let's assume filter includes any containing? But anyway.

First ArrowDown moves focus to first result (Banana?) Actually after typing "b", we expect results sorted alphabetically? Not sure. However after two ArrowDown presses, they assert that aria-selected on #autoComplete_result_0 is true. That suggests after pressing ArrowDown twice, the first result (index 0) gets selected again? Something off.

Let's examine observed logs: In observed.state.focusEvents etc., we saw key events: Tab, b, ArrowDown (prevented default?), ArrowDown prevented, l keydown not prevented, ArrowDown prevented, Enter prevented. So they typed "b", then ArrowDown, ArrowDown, typed "l", ArrowDown, Enter.

They expected after typing "b"+"l" i.e., "bl", the suggestions would be filtered to those starting with "bl": Blackberry, Blackcurrant, Blueberry, Boysenberry? Actually also "Bilberry"? No, Bilberry starts with "bi". So after typing "bl", the list should be Blackberry, Blackcurrant, Blueberry, Boysenberry. They then pressed ArrowDown (maybe to move to first result?). Then they pressed Enter expecting to select highlighted suggestion which should be Blackberry (the first). However the observed form data after Enter was "Blueberry". So something went wrong: the highlighted suggestion was not the first but perhaps third? Or the selection logic incorrectly mapping.

Observed after step: before Enter, the input field had aria-activedescendant="autoComplete_result_0". And the HTML snippet before Enter shows aria-activedescendant set to autoComplete_result_0. After Enter, the form data shows fruit = ["Blueberry"] meaning the value inserted was Blueberry, not Blackberry. How could that happen? Possibly the onSelection callback used feedback.selection.value where selection is based on dataFeedback.results[currentFocus] but maybe the results array is not aligned with DOM indices due to filtering or slicing? Let's look at the code.

In navigationController.js, the navigation function handles keydown. On Enter (keyCode 13), it prevents default, then if currentFocus > -1, it does: if (list) list[currentFocus].click();

So it triggers a click on the list item element at index currentFocus. The click handler in listController.js (generateList) adds click listener to each resultItem, which prepares dataFeedback and calls config.onSelection(dataFeedback) if set.

Thus the onSelection receives dataFeedback with selection: {...item, index}. The item is from data.results[index] (the data passed to generateList). In generateList, they iterate over data.results (which is the matches array sliced to maxResults? Actually data.results is the dataFeedback.results which is results.slice(0, this.maxResults) from start method. So data.results is the truncated list (maxResults). The index in the loop is the index within that truncated list.

Thus when click occurs, the item corresponds to data.results[index] which is the truncated list.

Now, what about currentFocus? It is updated via update function on arrow down/up. The update function increments/decrements currentFocus, then calls addActive(list) where list is the DOM nodes (list items). addActive removes aria-selected from all, then sets currentFocus within bounds (wrap-around), then sets aria-selected on list[currentFocus] and also sets config.inputField.setAttribute("aria-activedescendant", list[currentFocus].id).

Thus currentFocus tracks the index into the list DOM nodes (which are in same order as data.results). Good.

Now why did Enter cause selection of Blueberry instead of Blackberry? Let's reconstruct the state after typing "bl" and pressing ArrowDown once (since they pressed ArrowDown after typing l). Actually sequence: after typing "l", they pressed ArrowDown (once) then Enter. According to journey: after typing l, they asserted that #autoComplete_result_0 text is "Blackberry". That suggests after typing "bl", the first result (index 0) is Blackberry. Then they pressed ArrowDown (once) and expected aria-selected on #autoComplete_result_0 still true? Wait the assertion after that ArrowDown is: [{kind":"attribute","name":"aria-selected","selector":"#autoComplete_result_0","value":"true"}]. That means after pressing ArrowDown, they still expect the first result to be selected? That seems odd unless ArrowDown does nothing because maybe list length is 1? But they'd have multiple results.

Maybe the test expects that after typing "bl", the list is filtered to only Blackberry? Let's check data: src includes Banana, Bilberry, Blackberry, Blackcurrant, Blueberry, Boysenberry, Cranberry. Filter for "bl" (case-insensitive) yields Blackberry, Blackcurrant, Blueberry, Boysenberry. That's four results. So not one.

But the test's assertion after typing l: they assert that #autoComplete_result_0 text is "Blackberry". That's correct: first result is Blackberry.

Then they press ArrowDown (once) and assert that aria-selected on #autoComplete_result_0 is true. That would mean after pressing Down, the first item remains selected. That would happen if the Down key handler does not increment focus, maybe because they treat Down as moving focus but they also wrap? Actually if currentFocus starts at -1 (no focus), first Down increments to 0, selects item 0. Then second Down increments to 1, selects item 1. But they only pressed Down once after typing l. Yet they assert that result_0 is selected. So maybe before typing l, currentFocus was something else? Let's see earlier steps: after typing b, they pressed ArrowDown twice (two downs) and asserted that after second Down, aria-selected on result_0 true. That suggests after typing b, the list is longer (maybe 7 results). Two downs from -1 => 0 then 1? Actually start currentFocus = -1. First Down => 0 (select first). Second Down => 1 (select second). But they assert result_0 selected after second Down. So something inconsistent.

Thus likely the bug is that the navigation controller's update function treats arrow down as increasing currentFocus, but they also call addActive which wraps if out of bounds. However they might be resetting currentFocus incorrectly on each keystroke due to some other logic.

Look at navigationController.js: The navigate function is attached as keydown listener. Inside, they define update(event, list, state, config). The state param indicates whether arrow Down/Up (true for Down, false for Up). They call update with state true for Down (keyCode 40 or 9) and false for Up (38 or 9). Wait they also treat TAB as both up and down? Actually they have else if (event.keyCode === 9) for both up and down? They have:

else if (event.keyCode === 40 || event.keyCode === 9) {
   // Update list items state
   update(event, list, true, config);
} else if (event.keyCode === 38 || event.keyCode === 9) {
   // Update list items state
   update(event, list, false, config);
}

So pressing Tab triggers both down and up? Actually first condition matches for 40 or 9, so Tab goes into first block (state true). The second condition also matches for 38 or 9, but because it's else if, it won't run if first matched. So Tab triggers down only. That's okay.

Now the issue: In observed keyEvents, they saw defaultPrevented:true for ArrowDown events, meaning the navigation handler prevented default (good). They also saw defaultPrevented:false for 'l' key (meaning not prevented). That's fine.

Now why after typing "bl" and pressing Down once, the selection stayed on first item? Let's simulate: Suppose after typing "bl", the list is generated and navigation initialized. The navigation function sets currentFocus = -1 initially (reset focus state). Then on first Down, update called with state true: currentFocus++ => becomes 0. Then addActive(list) called. addActive removes aria-selected from all, then if currentFocus >= list.length set to 0; if <0 set to length-1; then sets aria-selected on list[currentFocus] and sets aria-activedescendant.

Thus after first Down, currentFocus = 0, item 0 selected. Good.

Now they pressed Enter. In navigation, on Enter (keyCode 13): event.preventDefault(); if (currentFocus > -1) { if (list) list[currentFocus].click(); }

Thus it clicks item at index currentFocus (0). So should select first item (Blackberry). Yet observed value is Blueberry (third? Actually index 2 if list: Blackberry(0), Blackcurrant(1), Blueberry(2), Boysenberry(3)). So why did clicking item at index 0 produce Blueberry? Perhaps the list items' innerHTML is set to item.match, which may be the highlighted matched substring? In Item.js, they set result.innerHTML = item.match; where item.match is the matched substring? Let's check dataController: listMatchingResults returns objects with match property (maybe the matched substring?). Indeed in listMatchingResults, they push { index, match, value: record }. So match is something like the matched portion? Probably the searchEngine returns true/false or maybe the matched substring? In default searchEngine (imported from ../services/search) unknown. But likely match is the matched substring (maybe the whole value?). If match is just the matched substring (like "bl"?) then innerHTML would be just "bl", not the full fruit name. But the observed text of #autoComplete_result_0 after typing l was "Blackberry". So innerHTML must be full name. So match likely is the full value.

Nevertheless, click handler uses item (the original object) which includes .value (the original record). In generateList, they call createItem(item, index, config) where item is data.results[index] (which contains match, index, value). Then they attach click listener that builds dataFeedback with selection: {...item, index}. So selection.value = item.value (the original record). So clicking should yield the correct fruit.

Thus why did we get Blueberry? Maybe the list items were misaligned due to the list being rebuilt after each keystroke causing DOM nodes to be reused incorrectly? Or maybe the click handler uses the item from closure that got overwritten due to variable reuse? Let's examine generateList more closely:

const generateList = (config, data, matches) => {
  const list = createList(config);
  config.inputField.setAttribute("aria-expanded", true);
  for (let index = 0; index < data.results.length; index++) {
    const item = data.results[index];
    const resultItem = createItem(item, index, config);
    resultItem.addEventListener("click", (event) => {
      const dataFeedback = {
        event,
        matches,
        input: data.input,
        query: data.query,
        results: data.results,
        selection: {
          ...item,
          index,
        },
      };
      if (config.onSelection) config.onSelection(dataFeedback);
    });
    list.appendChild(resultItem);
  }
  return list;
};

Note: The variable `item` is captured in the closure of the click listener. Since it's reassigned each iteration, but using `let item = data.results[index];` ensures each iteration gets its own binding. So fine.

Thus click should pass correct item.

Yet observed value is Blueberry. Could be that the list currently displayed after typing "bl" and pressing Down once is not the list for "bl" but maybe the list from previous state (after typing "b")? Because they typed "l" after the two downs? Wait sequence: type b, down, down, type l, down, enter. Actually after typing b and two downs, they had selected something (maybe result_0? unclear). Then they typed "l", which appended to input making "bl". This should trigger a new search and regenerate list. However, maybe the input event listener (debounced) didn't fire because they typed "l" quickly after the downs? But they observed a keydown for 'l' with defaultPrevented:false, meaning the input event likely fired after keyup? Actually input event fires on input change, not keydown. The debounced hook is attached to input event. So after typing l, the input field value becomes "bl". The input event triggers after the keydown? Usually after the character is added, input event fires synchronously? Might be after the keyup. But they pressed Down after l keydown, before input event maybe? Let's see timeline: keydown l (defaultPrevented:false) -> keyup l -> input event fires (maybe after keyup). Then they pressed ArrowDown keydown (while input event may not have fired yet if debounce delay >0). debounce is 0 in config (see index.html: they passed debounce: 0? Actually in index.html they instantiate autoComplete with no debounce option, default is 0). So debounce zero means hook fires immediately (setTimeout with 0). So input event should fire before next tick.

Thus after typing l, the input event should trigger compose, which calls dataStore (if needed) then start, which generates list based on query "bl". Then navigation is reinitialized? Actually navigation is attached once in init() via navigate(this, dataFeedback) inside start? Wait navigation is called inside start after generating list: navigate(this, dataFeedback); This attaches a keydown listener each time start is called? Let's see navigationController.js: const navigate = (config, dataFeedback) => { ... config.inputField.addEventListener("keydown", navigate); }; So each time start is called, navigate is called, which adds another keydown listener! That means multiple listeners accumulate. That could cause weird behavior: on each keydown, multiple navigation handlers fire, possibly causing state conflicts.

Indeed, in start method: they call navigate(this, dataFeedback); which adds a keydown listener. They do not remove previous listeners. So each time a new list is generated (on each input), another keydown listener is added, leading to multiple handlers. The navigation function uses a closure variable `let currentFocus = -1;` defined inside navigate, so each listener has its own currentFocus variable. When a keydown occurs, all listeners fire, each updating its own currentFocus and acting on the list. This could cause the wrong item to be clicked.

Specifically, after typing "b", first list generated, navigation listener added (listener A). Then after pressing ArrowDown twice, listener A's currentFocus changes accordingly. Then typing "l" triggers new input, generate new list, start called again, navigate adds listener B. Now we have two listeners: A and B. When ArrowDown is pressed after l, both listeners A and B fire. Listener A still references the old list? Actually listener A's closure captures config and dataFeedback from the time it was created (the first list). Its `list` variable is obtained by `let list = document.getElementById(config.resultsList.idName);` each time navigation runs, it queries the DOM for the list element. At that moment, the list in DOM is the new list (for "bl") because the old list was removed by closeAllLists before generating new list? In start, they call closeAllLists(this); before generating list. So old list removed, new list added. So both listeners will find the same current list element (the new one). However each listener has its own currentFocus variable, starting at -1. So when ArrowDown fires, listener A increments its currentFocus from -1 to 0, calls addActive on the list (sets aria-selected on item 0). Listener B also increments its own currentFocus from -1 to 0, calls addActive again (which removes aria-selected from all then sets on item 0). The net effect is still item 0 selected. However they also set aria-activedescendant each time (same). So still fine.

But then Enter key: both listeners fire. Listener A: currentFocus is 0 (from previous Down? Actually after two Downs earlier, listener A's currentFocus might be 2? Let's compute: After typing b, listener A created. Then first Down: listener A currentFocus ->0, selects item0. Second Down: listener A currentFocus ->1, selects item1. Then after typing l, listener B created with currentFocus -1. Then Down after l: both listeners fire. Listener A: currentFocus increments from 1 to 2, selects item2 (which is Blueberry). Listener B: currentFocus increments from -1 to 0, selects item0 (Blackberry). Then addActive is called twice: first listener A's addActive removes all aria-selected, sets item2 selected. Then listener B's addActive removes all aria-selected, sets item0 selected. The order of execution matters: which listener runs first? They are registered in order: first listener A added earlier, then listener B added later. When an event fires, listeners are called in the order they were added. So listener A runs first, then listener B. So after listener A: item2 selected. Then listener B runs: removes aria-selected from all, sets item0 selected. Final state: item0 selected (Blackberry). That matches expectation after Down: aria-selected on result_0 true. Good.

Now Enter key: both listeners fire again. Listener A runs first: its currentFocus is currently? After the Down after l, listener A's currentFocus ended at 2 (since it incremented to 2). Listener B's currentFocus ended at 0. So on Enter, listener A: currentFocus > -1 (2) => triggers click on list[currentFocus] i.e., item2 (Blueberry). Listener B: currentFocus 0 => triggers click on item0 (Blackberry). The click handlers will call onSelection with respective items. Which one wins? The onSelection callback (from index.html) sets input.value = feedback.selection.value. If both fire, the second one will overwrite the first. Order: listener A first, sets input.value = Blueberry. Then listener B runs, sets input.value = Blackberry. Final would be Blackberry. But observed final value is Blueberry, meaning listener B's click didn't override, or listener B's click didn't happen (maybe because currentFocus > -1 condition false? But it's 0). Or maybe listener B's click didn't fire because list variable null? Let's see: In navigation's Enter handling: if (currentFocus > -1) { if (list) list[currentFocus].click(); } They compute list each time via let list = document.getElementById(config.resultsList.idName); So if list exists, they click.

